import { createHash } from "node:crypto";
export default async ({ messages, previous }, ctx) => {
  for (let index = (previous ?? -1) + 1; index < messages.length; index++) {
    const msg = messages[index];
    const key = "outlook-reply:" + createHash("sha256").update(msg.messageId).digest("hex");
    if (!(await ctx.state.get(key)))
      return {
        index,
        more: true,
        msg,
        key,
        endpoint: "/me/messages/" + encodeURIComponent(msg.messageId),
      };
  }
  return { index: messages.length, more: false, msg: null, key: "", endpoint: "" };
};

