function messageKey(value) {
  return typeof value === "string" && /^[A-Za-z0-9_+/=-]{1,512}$/.test(value);
}

function confirmDraft(status, draft, original) {
  if (
    status !== 201 ||
    !messageKey(draft?.id) ||
    draft.id === original.messageId ||
    draft.isDraft !== true ||
    draft.conversationId !== original.conversationId
  ) {
    throw new Error(
      "Outlook did not confirm a draft on this thread. Check Drafts before repeating.",
    );
  }
  return {
    messageId: original.messageId,
    conversationId: original.conversationId,
    draftId: draft.id,
    isDraft: true,
  };
}

export default async ({ status, body, original, key }, ctx) => {
  const result = confirmDraft(status, body, original);
  await ctx.state.set(key, result);
  return { result };
};
